In MQL5, you can programmatically set your stop loss to be 1% of your trading balance. Here's how to do it:

## Method 1: Calculate Stop Loss Based on Position Size

```mql5
input double RiskPercent = 1.0; // Risk percentage per trade

// Function to calculate stop loss distance based on 1% risk
double CalculateStopLossDistance(string symbol, double lotSize, ENUM_ORDER_TYPE orderType)
{
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = balance * (RiskPercent / 100.0);

    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);

    // Calculate stop loss distance in points
    double stopLossPoints = (riskAmount / (lotSize * tickValue)) * tickSize / point;

    return NormalizeDouble(stopLossPoints * point, _Digits);
}
```

## Method 2: Calculate Lot Size Based on Stop Loss Distance

```mql5
// Function to calculate lot size for a given stop loss distance
double CalculateLotSize(string symbol, double stopLossPoints)
{
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = balance * (RiskPercent / 100.0);

    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);

    double lotSize = riskAmount / (stopLossPoints * tickValue / tickSize);

    // Normalize lot size according to broker specifications
    double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    lotSize = MathFloor(lotSize / lotStep) * lotStep;
    lotSize = MathMax(minLot, MathMin(maxLot, lotSize));

    return NormalizeDouble(lotSize, 2);
}
```

## Complete Example: Opening a Trade with 1% Risk

```mql5
#include <Trade\Trade.mqh>

input double RiskPercent = 1.0; // Risk percentage per trade
input int StopLossPips = 50;    // Stop loss in pips

CTrade trade;

void OpenBuyWithRiskManagement()
{
    string symbol = _Symbol;
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);

    // Get current price
    double ask = SymbolInfoDouble(symbol, SYMBOL_ASK);
    double bid = SymbolInfoDouble(symbol, SYMBOL_BID);

    // Calculate stop loss price (50 pips below entry for buy)
    double stopLossPrice = ask - (StopLossPips * point * 10); // *10 for 5-digit brokers
    double stopLossDistance = ask - stopLossPrice;

    // Calculate lot size based on 1% risk
    double lotSize = CalculateLotSizeForRisk(symbol, stopLossDistance);

    // Set take profit (optional)
    double takeProfitPrice = ask + (StopLossPips * 2 * point * 10); // 2:1 RR ratio

    // Open position
    trade.Buy(lotSize, symbol, ask, stopLossPrice, takeProfitPrice, "1% Risk Trade");
}

double CalculateLotSizeForRisk(string symbol, double stopLossDistance)
{
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = balance * (RiskPercent / 100.0);

    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double contractSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_CONTRACT_SIZE);

    // Calculate lot size
    double lotSize = riskAmount / (stopLossDistance / _Point * tickValue);

    // Normalize lot size
    double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
    double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

    lotSize = MathFloor(lotSize / lotStep) * lotStep;
    lotSize = MathMax(minLot, MathMin(maxLot, lotSize));

    return lotSize;
}
```

## Alternative: Using Fixed Lot Size

If you prefer to use a fixed lot size and adjust the stop loss distance:

```mql5
void SetStopLossBasedOnRisk(ulong ticket, double lotSize)
{
    if(!PositionSelectByTicket(ticket))
        return;

    string symbol = PositionGetString(POSITION_SYMBOL);
    double openPrice = PositionGetDouble(POSITION_PRICE_OPEN);
    ENUM_POSITION_TYPE posType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);

    double balance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = balance * (RiskPercent / 100.0);

    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double point = SymbolInfoDouble(symbol, SYMBOL_POINT);

    // Calculate stop loss distance
    double stopLossPoints = (riskAmount / (lotSize * tickValue));

    double stopLossPrice;
    if(posType == POSITION_TYPE_BUY)
        stopLossPrice = openPrice - (stopLossPoints * point);
    else
        stopLossPrice = openPrice + (stopLossPoints * point);

    // Modify position
    trade.PositionModify(ticket, stopLossPrice, PositionGetDouble(POSITION_TP));
}
```

## Important Considerations:

1. **Account Currency**: Make sure your calculations consider the account currency vs. the quote currency of the pair.

2. **Broker Digits**: Adjust for 4/5 digit brokers (multiply pips by 10 for 5-digit brokers).

3. **Spread**: Consider the spread when calculating exact risk.

4. **Margin Requirements**: Ensure you have enough margin for the calculated lot size.

5. **Slippage**: Real execution might differ from calculated values.

The key is to either:
- Calculate the appropriate lot size for a fixed stop loss distance (recommended)
- Calculate the stop loss distance for a fixed lot size

Most professional traders prefer the first approach as it gives more consistent risk management.

